func emailDeliveryKind(kind string) string {
	switch kind {
	case "OrderCreated":
		return "Customer order received"
	case "OrderPaid":
		return "Customer payment confirmed"
	case "SellerOrderShipped":
		return "Customer dispatch update"
	case "New paid order":
		return "Seller new order"
	default:
		return kind
	}
}

func emailDeliveryState(state string) string {
	switch state {
	case "submitting":
		return "Awaiting provider confirmation"
	case "accepted":
		return "Accepted by Resend"
	case "delayed":
		return "Delivery delayed"
	case "delivered":
		return "Delivered to mail server"
	case "bounced":
		return "Bounced"
	case "failed":
		return "Delivery failed"
	case "suppressed":
		return "Suppressed by Resend"
	case "complained":
		return "Reported as spam"
	case "rejected":
		return "Send request rejected"
	default:
		return "Needs investigation"
	}
}

